import { resolveOrganizationWhatsAppCredentials } from "../../_shared/omnichannelPublicApi/resolveOrganizationWhatsAppCredentials.ts";

function resolveFormId(body: Record<string, unknown>, formData: Record<string, unknown> | null): string | null {
  const top = body.form_id != null ? String(body.form_id).trim() : "";
  if (top) return top;
  const nested = formData?.form_id != null ? String(formData.form_id).trim() : "";
  return nested || null;
}

export async function handleLeads(
  admin: SupabaseClient,
  ctx: OmnichannelApiTokenContext,
  body: Record<string, unknown>,
  corsHeaders: Record<string, string>,
): Promise<Response> {
  try {
    const extracted = extractLeadFormPayload(body);
    if (!extracted.ok) {
      return apiError(extracted.error, "VALIDATION_ERROR", 422, corsHeaders);
    }

    const { core, formData } = extracted;
    const name = core.name;
    const phoneRaw = core.phone_number ? normalizePhone(core.phone_number) : "";
    const emailRaw = core.email ? normalizeEmail(core.email) : "";
    const notes = core.notes;
    const sessionId = core.session_id;
    const formId = resolveFormId(body, formData);

    if (!name) {
      return apiError("name wajib diisi.", "VALIDATION_ERROR", 422, corsHeaders);
    }
    if (!phoneRaw && !emailRaw) {
      return apiError("Minimal salah satu dari phone_number atau email wajib diisi.", "VALIDATION_ERROR", 422, corsHeaders);
    }

    let attribution: Record<string, unknown> | null = null;
    let attributionLabel: string | null = null;
    let gclid: string | null = null;
    let fbclid: string | null = null;

    if (sessionId && isUuid(sessionId)) {
      const { data: session } = await admin
        .from("analytics_sessions")
        .select("*")
        .eq("id", sessionId)
        .eq("web_id", ctx.webId)
        .maybeSingle();

      if (session) {
        const marketing = resolveSessionMarketingAttribution(sessionId, ctx.webId, session);
        attribution = marketing.attribution;
        attributionLabel = marketing.attributionLabel;
        gclid = marketing.gclid;
        fbclid = marketing.fbclid;
      }
    }

    const actor = await getOrCreateSystemActor(admin, ctx.organizationId);
    const statusId = await resolveLeadStatusId(
      admin,
      ctx.organizationId,
      core.status ?? "new",
    );

    const now = new Date().toISOString();
    let leadId: string;

    const floatingStub =
      sessionId && isUuid(sessionId)
        ? await findFloatingStubLead(admin, ctx.organizationId, ctx.webId, sessionId)
        : null;

    if (floatingStub) {
      leadId = floatingStub.leadId;

      const leadPatch: Record<string, unknown> = {
        client: name,
        title: "Lead Website",
        source: "Website",
        phone_number: phoneRaw || null,
        email: emailRaw || null,
        status_id: statusId,
        updated_at: now,
      };
      if (attribution) {
        leadPatch.attribution = attribution;
        leadPatch.attribution_label = attributionLabel;
        leadPatch.gclid = gclid;
        leadPatch.fbclid = fbclid;
      }

      const { error: leadUpdErr } = await admin
        .from("leads")
        .update(leadPatch)
        .eq("id", leadId)
        .eq("organization_id", ctx.organizationId);

      if (leadUpdErr) {
        console.error("handleLeads upgrade floating stub:", leadUpdErr);
        return apiError("Gagal memperbarui lead.", "INTERNAL_ERROR", 500, corsHeaders, leadUpdErr.message);
      }

      if (floatingStub.submissionId) {
        const { error: subUpdErr } = await admin
          .from("lead_submissions")
          .update({
            form_id: formId,
            name,
            phone_number: phoneRaw || null,
            email: emailRaw || null,
            notes,
            form_data: formData,
            status: "submitted",
            submitted_at: now,
            updated_at: now,
          })
          .eq("id", floatingStub.submissionId)
          .eq("organization_id", ctx.organizationId);

        if (subUpdErr) {
          console.error("handleLeads upgrade floating submission:", subUpdErr);
          return apiError("Gagal memperbarui profil lead.", "INTERNAL_ERROR", 500, corsHeaders, subUpdErr.message);
        }
      } else {
        const { error: subInsErr } = await admin.from("lead_submissions").insert({
          organization_id: ctx.organizationId,
          lead_id: leadId,
          web_id: ctx.webId,
          form_id: formId,
          name,
          phone_number: phoneRaw || null,
          email: emailRaw || null,
          notes,
          form_data: formData,
          status: "submitted",
          is_active: true,
          submitted_at: now,
          updated_at: now,
        });

        if (subInsErr) {
          console.error("handleLeads insert submission after stub:", subInsErr);
          return apiError("Gagal menyimpan profil lead.", "INTERNAL_ERROR", 500, corsHeaders, subInsErr.message);
        }
      }
    } else {
      leadId = crypto.randomUUID();

      const { error: leadErr } = await admin.from("leads").insert({
        id: leadId,
        client: name,
        title: "Lead Website",
        category: "Website API",
        created_by: actor.userId,
        created_by_name: actor.displayName,
        assignee: "Unassigned",
        organization_id: ctx.organizationId,
        source: "Website",
        status_id: statusId,
        phone_number: phoneRaw || null,
        email: emailRaw || null,
        attribution,
        attribution_label: attributionLabel,
        web_id: ctx.webId,
        analytics_session_id: sessionId && isUuid(sessionId) ? sessionId : null,
        gclid,
        fbclid,
        created_at: now,
        updated_at: now,
      });

      if (leadErr) {
        console.error("handleLeads insert leads:", leadErr);
        return apiError("Gagal menyimpan lead.", "INTERNAL_ERROR", 500, corsHeaders, leadErr.message);
      }

      const { error: subErr } = await admin.from("lead_submissions").insert({
        organization_id: ctx.organizationId,
        lead_id: leadId,
        web_id: ctx.webId,
        form_id: formId,
        name,
        phone_number: phoneRaw || null,
        email: emailRaw || null,
        notes,
        form_data: formData,
        status: "submitted",
        is_active: true,
        submitted_at: now,
        updated_at: now,
      });

      if (subErr) {
        console.error("handleLeads insert lead_submissions:", subErr);
        await admin.from("leads").delete().eq("id", leadId);
        return apiError("Gagal menyimpan profil lead.", "INTERNAL_ERROR", 500, corsHeaders, subErr.message);
      }
    }

    let whatsappStatus: "pending" | "sent" | "failed" | "skipped" = "skipped";
    let whatsappMessageId: string | null = null;
    let whatsappSkipReason: string | null = null;
    let whatsappConversationId: string | null = null;
    let whatsappDebug: LeadWhatsAppDebugInfo | null = null;

    const hasConsent = parseLeadConsent(body, formData);

    const { data: orgSettings } = await admin
      .from("organization_omnichannel_api_settings")
      .select("default_whatsapp_lead_template_name, default_whatsapp_lead_template_language")
      .eq("organization_id", ctx.organizationId)
      .maybeSingle();

    const templateName =
      ctx.whatsappLeadTemplateName ??
      orgSettings?.default_whatsapp_lead_template_name ??
      null;

    const orgTemplateLanguage = orgSettings?.default_whatsapp_lead_template_language ?? null;

    if (!hasConsent) {
      whatsappStatus = "skipped";
      whatsappSkipReason = "no_consent";
    } else if (!phoneRaw) {
      whatsappStatus = "skipped";
      whatsappSkipReason = "no_phone";
    } else if (!templateName) {
      whatsappStatus = "skipped";
      whatsappSkipReason = "no_template";
    } else {
      const waResult = await triggerLeadWhatsApp(admin, {
        organizationId: ctx.organizationId,
        webId: ctx.webId,
        templateName,
        orgTemplateLanguage,
        phoneNumber: phoneRaw,
        name,
        email: emailRaw || null,
        formData,
      });
      whatsappStatus = waResult.status;
      whatsappMessageId = waResult.messageId;
      whatsappSkipReason = waResult.skipReason ?? null;
      if (waResult.status === "failed" && waResult.debug) {
        whatsappDebug = waResult.debug;
      } else if (waResult.status === "skipped" && waResult.debug) {
        whatsappDebug = waResult.debug;
      }

      if (waResult.status === "failed") {
        console.error("handleLeads WhatsApp failed:", {
          lead_id: leadId,
          organization_id: ctx.organizationId,
          web_id: ctx.webId,
          template_name: templateName,
          mapping_source: waResult.mappingSource,
          param_count: waResult.paramCount,
          meta_error_code: waResult.metaErrorCode,
          error: waResult.error,
        });
      } else if (waResult.status === "sent" && waResult.messageId) {
        const creds = await resolveOrganizationWhatsAppCredentials(admin, ctx.organizationId, {
          webId: ctx.webId,
        });
        if (creds.ok) {
          const templateLanguage = waResult.templateLanguage ?? orgTemplateLanguage ?? "id";
          const bodyPreview = await buildLeadWhatsAppStoredBody(admin, {
            organizationId: ctx.organizationId,
            whatsappAccountId: creds.credentials.whatsappAccountId,
            phoneNumberId: creds.credentials.phoneNumberId,
            accessToken: creds.credentials.accessToken,
            templateName,
            templateLanguage,
            bodyParams: waResult.bodyParams ?? [],
          });
          const persisted = await persistLeadWhatsAppThread(admin, {
            organizationId: ctx.organizationId,
            leadId,
            webId: ctx.webId,
            phoneNumber: phoneRaw,
            customerName: name,
            waMessageId: waResult.messageId,
            templateName,
            templateLanguage,
            bodyPreview,
            bodyParams: waResult.bodyParams ?? [],
            rawMetadata: waResult.rawMetadata ?? null,
            whatsappAccountId: creds.credentials.whatsappAccountId,
            phoneNumberId: creds.credentials.phoneNumberId,
          });
          if (persisted.ok) {
            whatsappConversationId = persisted.conversationId;
          } else {
            console.error("handleLeads persistLeadWhatsAppThread failed:", persisted.error);
            whatsappSkipReason = `persist_failed:${persisted.error}`.slice(0, 500);
          }
        } else {
          console.error("handleLeads persist skipped — WA credentials:", creds.error);
          whatsappSkipReason = "persist_failed:wa_not_configured";
        }
      }
    }

    const waSentAt = whatsappStatus === "sent" ? new Date().toISOString() : null;

    await admin
      .from("lead_submissions")
      .update({
        whatsapp_status: whatsappStatus,
        whatsapp_message_id: whatsappMessageId,
        whatsapp_skip_reason: whatsappSkipReason,
        whatsapp_sent_at: waSentAt,
        whatsapp_conversation_id: whatsappConversationId,
        updated_at: new Date().toISOString(),
      })
      .eq("lead_id", leadId)
      .eq("organization_id", ctx.organizationId);

    const { data: ticketRow } = await admin.from("leads").select("ticket_id").eq("id", leadId).single();
    const finalTicketId = ticketRow?.ticket_id ?? null;

    const responseBody: Record<string, unknown> = {
        lead_id: leadId,
        ticket_id: finalTicketId,
        whatsapp_ticket_id: finalTicketId,
        session_id: sessionId,
        attribution,
        whatsapp_status: whatsappStatus,
        whatsapp_message_id: whatsappMessageId,
        whatsapp_skip_reason: whatsappSkipReason,
        whatsapp_conversation_id: whatsappConversationId,
      };

    if (whatsappStatus === "failed" && whatsappDebug) {
      responseBody.whatsapp_debug = whatsappDebug;
    } else if (whatsappStatus === "skipped" && whatsappDebug) {
      responseBody.whatsapp_debug = whatsappDebug;
    }

    return apiSuccess(responseBody, 201, corsHeaders);
  } catch (e) {
    console.error("handleLeads:", e);
    return apiError("Kesalahan server saat menyimpan lead.", "INTERNAL_ERROR", 500, corsHeaders);
  }
}

export async function findLeadByPhoneAndEmail(
  admin: SupabaseClient,
  organizationId: string,
  phone: string,
  email: string,
): Promise<string | null> {
  const normPhone = normalizePhone(phone);
  const normEmail = normalizeEmail(email);
  if (!normPhone || !normEmail) return null;

  const { data: submissions } = await admin
    .from("lead_submissions")
    .select("lead_id, phone_number, email, submitted_at")
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .ilike("email", normEmail)
    .order("submitted_at", { ascending: false });

  for (const row of submissions ?? []) {
    if (normalizePhone(row.phone_number) === normPhone && row.lead_id) {
      return String(row.lead_id);
    }
  }

  const { data: leads } = await admin
    .from("leads")
    .select("id, phone_number, email, created_at")
    .eq("organization_id", organizationId)
    .ilike("email", normEmail)
    .order("created_at", { ascending: false });

  for (const row of leads ?? []) {
    if (normalizePhone(row.phone_number) === normPhone) {
      return String(row.id);
    }
  }

  return null;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { OmnichannelApiTokenContext } from "../../_shared/omnichannelPublicApi/auth.ts";
import { kickOfflineConversionsServer } from "../../_shared/omnichannelPublicApi/kickOfflineConversions.ts";
import { createLeadConversionSalesActivity } from "../../_shared/omnichannelPublicApi/createLeadConversionSalesActivity.ts";
import {
  getOrCreateSystemActor,
  resolveConvertedStatusId,
} from "../../_shared/omnichannelPublicApi/leadStatusMap.ts";
import {
  normalizeEmail,
  normalizePhone,
} from "../../_shared/omnichannelPublicApi/phoneNormalize.ts";
import { apiError, apiSuccess } from "../../_shared/omnichannelPublicApi/response.ts";
import { findLeadByPhoneAndEmail } from "./leadsHandler.ts";
import { triggerInvoiceWhatsApp } from "../../_shared/omnichannelPublicApi/triggerInvoiceWhatsApp.ts";

export async function handleInvoiceTrigger(
  admin: SupabaseClient,
  ctx: OmnichannelApiTokenContext,
  body: Record<string, unknown>,
  corsHeaders: Record<string, string>,
  supabaseUrl: string,
  serviceRoleKey: string,
): Promise<Response> {
  try {
    const invoiceNumber = String(body.invoice_number ?? "").trim();
    const amount = Number(body.amount);
    const phoneRaw = String(body.phone_number ?? "").trim();
    const emailRaw = String(body.email ?? "").trim();
    const customerName = body.customer_name != null ? String(body.customer_name).trim() : null;
    const items = body.items;

    if (!invoiceNumber) {
      return apiError("invoice_number wajib diisi.", "VALIDATION_ERROR", 422, corsHeaders);
    }
    if (!Number.isFinite(amount) || amount <= 0) {
      return apiError("amount harus angka positif.", "VALIDATION_ERROR", 422, corsHeaders);
    }
    if (!phoneRaw || !emailRaw) {
      return apiError("phone_number dan email wajib diisi untuk pencocokan lead.", "VALIDATION_ERROR", 422, corsHeaders);
    }
    if (!Array.isArray(items) || items.length === 0) {
      return apiError("items harus array JSON tidak kosong.", "VALIDATION_ERROR", 422, corsHeaders);
    }

    const { data: existing } = await admin
      .from("sales_invoices")
      .select("id")
      .eq("organization_id", ctx.organizationId)
      .eq("invoice_number", invoiceNumber)
      .maybeSingle();

    if (existing?.id) {
      return apiError("Nomor invoice sudah terdaftar.", "CONFLICT", 409, corsHeaders, {
        invoice_number: invoiceNumber,
      });
    }

    const leadId = await findLeadByPhoneAndEmail(admin, ctx.organizationId, phoneRaw, emailRaw);

    const invoiceId = crypto.randomUUID();
    const now = new Date().toISOString();

    const { error: insertErr } = await admin.from("sales_invoices").insert({
      id: invoiceId,
      organization_id: ctx.organizationId,
      web_id: ctx.webId,
      lead_id: leadId,
      invoice_number: invoiceNumber,
      amount,
      items,
      whatsapp_status: "pending",
      customer_phone: normalizePhone(phoneRaw),
      customer_email: normalizeEmail(emailRaw),
      created_at: now,
      updated_at: now,
    });

    if (insertErr) {
      console.error("handleInvoiceTrigger insert:", insertErr);
      return apiError("Gagal menyimpan invoice.", "INTERNAL_ERROR", 500, corsHeaders, insertErr.message);
    }

    let converted = false;
    let salesActivityId: string | null = null;
    if (leadId) {
      const convertedStatusId = await resolveConvertedStatusId(admin, ctx.organizationId);
      if (convertedStatusId) {
        const { error: leadUpdErr } = await admin
          .from("leads")
          .update({
            status_id: convertedStatusId,
            converted_at: now,
            updated_at: now,
          })
          .eq("id", leadId)
          .eq("organization_id", ctx.organizationId);

        if (!leadUpdErr) {
          converted = true;

          const { data: leadRow } = await admin
            .from("leads")
            .select("client")
            .eq("id", leadId)
            .maybeSingle();

          const actor = await getOrCreateSystemActor(admin, ctx.organizationId);
          salesActivityId = await createLeadConversionSalesActivity(admin, {
            organizationId: ctx.organizationId,
            leadId,
            clientName: customerName ?? leadRow?.client ?? "Lead",
            clientPhone: normalizePhone(phoneRaw),
            clientEmail: normalizeEmail(emailRaw),
            createdByUserId: actor.userId,
            totalAmount: amount,
            items: items as unknown[],
            invoiceNumber,
          });

          const { data: settings } = await admin
            .from("organization_omnichannel_api_settings")
            .select("offline_conversion_enabled")
            .eq("organization_id", ctx.organizationId)
            .maybeSingle();

          const offlineEnabled = settings?.offline_conversion_enabled !== false;
          if (offlineEnabled) {
            kickOfflineConversionsServer({
              supabaseUrl,
              serviceRoleKey,
              organizationId: ctx.organizationId,
              leadId,
              salesActivityId,
            });
          }
        }
      }
    }

    let whatsappStatus = "pending";
    let whatsappMessageId: string | null = null;

    const { data: orgSettings } = await admin
      .from("organization_omnichannel_api_settings")
      .select("default_whatsapp_invoice_template_name, default_whatsapp_invoice_template_language")
      .eq("organization_id", ctx.organizationId)
      .maybeSingle();

    const templateName =
      ctx.whatsappInvoiceTemplateName ??
      orgSettings?.default_whatsapp_invoice_template_name ??
      null;

    const templateLanguage = orgSettings?.default_whatsapp_invoice_template_language ?? null;

    if (templateName && phoneRaw) {
      const waResult = await triggerInvoiceWhatsApp(admin, {
        organizationId: ctx.organizationId,
        webId: ctx.webId,
        templateName,
        templateLanguage,
        phoneNumber: phoneRaw,
        invoiceNumber,
        amount,
        customerName,
        items,
      });
      whatsappStatus = waResult.status;
      whatsappMessageId = waResult.messageId;

      await admin
        .from("sales_invoices")
        .update({
          whatsapp_status: whatsappStatus,
          whatsapp_message_id: whatsappMessageId,
          updated_at: new Date().toISOString(),
        })
        .eq("id", invoiceId);
    }

    return apiSuccess(
      {
        invoice_id: invoiceId,
        invoice_number: invoiceNumber,
        lead_id: leadId,
        lead_matched: Boolean(leadId),
        lead_converted: converted,
        sales_activity_id: salesActivityId,
        whatsapp_status: whatsappStatus,
        whatsapp_message_id: whatsappMessageId,
      },
      201,
      corsHeaders,
    );
  } catch (e) {
    console.error("handleInvoiceTrigger:", e);
    return apiError("Kesalahan server saat memproses invoice.", "INTERNAL_ERROR", 500, corsHeaders);
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { apiError } from "./response.ts";
import { buildCorsHeaders } from "./response.ts";

export type OmnichannelApiTokenType = "sdk" | "server" | "legacy_full";

export type OmnichannelApiTokenContext = {
  tokenId: string;
  organizationId: string;
  webId: string;
  allowedOrigins: string[];
  whatsappInvoiceTemplateName: string | null;
  whatsappLeadTemplateName: string | null;
  tokenType: OmnichannelApiTokenType;
};

const SDK_PATHS = new Set([
  "/api/v1/traffic-logs",
  "/api/v1/page-views/heartbeat",
  "/api/v1/click-events",
  "/api/v1/wa-link-clicks",
  "/api/v1/leads",
]);

const SERVER_PATHS = new Set(["/api/v1/orders/invoice-trigger"]);

const BROWSER_SEC_FETCH_SITES = new Set(["same-origin", "same-site", "cross-site"]);

/** Opsi A — invoice-trigger tidak boleh dipanggil dari browser (Origin / Sec-Fetch-Site). */
export function assertInvoiceNotFromBrowser(
  req: Request,
  corsHeaders: Record<string, string>,
): Response | null {
  const origin = req.headers.get("Origin")?.trim();
  if (origin) {
    return apiError(
      "invoice-trigger tidak boleh dipanggil dari browser. Gunakan token Server di backend (Edge Function / server).",
      "BROWSER_REQUEST_REJECTED",
      403,
      corsHeaders,
    );
  }

  const secFetchSite = req.headers.get("Sec-Fetch-Site")?.trim().toLowerCase();
  if (secFetchSite && BROWSER_SEC_FETCH_SITES.has(secFetchSite)) {
    return apiError(
      "invoice-trigger tidak boleh dipanggil dari browser. Gunakan token Server di backend (Edge Function / server).",
      "BROWSER_REQUEST_REJECTED",
      403,
      corsHeaders,
    );
  }

  return null;
}

export function assertPathAllowedForTokenType(
  path: string,
  tokenType: OmnichannelApiTokenType,
  corsHeaders: Record<string, string>,
): Response | null {
  if (tokenType === "legacy_full") return null;

  if (tokenType === "sdk") {
    if (SDK_PATHS.has(path)) return null;
    if (path === "/api/v1/orders/invoice-trigger") {
      return apiError(
        "Token tipe SDK tidak boleh memanggil invoice-trigger. Gunakan token Server di backend.",
        "FORBIDDEN",
        403,
        corsHeaders,
      );
    }
    return apiError(
      "Token tipe SDK tidak diizinkan untuk endpoint ini.",
      "FORBIDDEN",
      403,
      corsHeaders,
    );
  }

  if (tokenType === "server") {
    if (SERVER_PATHS.has(path)) return null;
    return apiError(
      "Token tipe Server hanya untuk invoice-trigger.",
      "FORBIDDEN",
      403,
      corsHeaders,
    );
  }

  return null;
}

function normalizeTokenType(value: unknown): OmnichannelApiTokenType {
  const t = String(value ?? "legacy_full").trim();
  if (t === "sdk" || t === "server" || t === "legacy_full") return t;
  return "legacy_full";
}

const RATE_LIMIT_PER_MINUTE = 100;
const MS_PER_DAY = 86_400_000;

/** True when expires_at is in the past (UTC). Null/empty = never expires. */
export function isOmnichannelApiTokenExpired(expiresAt: string | null | undefined): boolean {
  if (!expiresAt) return false;
  const ts = new Date(expiresAt).getTime();
  return Number.isFinite(ts) && ts < Date.now();
}

export function computeTokenExpiresAt(expiresInDays: number): string | null {
  if (!Number.isFinite(expiresInDays) || expiresInDays <= 0) return null;
  return new Date(Date.now() + expiresInDays * MS_PER_DAY).toISOString();
}

async function sha256Hex(input: string): Promise<string> {
  const data = new TextEncoder().encode(input);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function hashApiToken(plaintext: string): Promise<string> {
  return sha256Hex(plaintext);
}

export function generateApiTokenPlaintext(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  const random = Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
  return `sk_omni_${random}`;
}

export function extractBearerToken(authHeader: string | null): string {
  if (!authHeader?.startsWith("Bearer ")) return "";
  return authHeader.slice("Bearer ".length).trim();
}

export async function authenticateOmnichannelApiToken(
  admin: SupabaseClient,
  req: Request,
): Promise<{ ctx: OmnichannelApiTokenContext; corsHeaders: Record<string, string> } | { error: Response }> {
  const origin = req.headers.get("Origin");
  const bearer = extractBearerToken(req.headers.get("Authorization"));

  if (!bearer || !bearer.startsWith("sk_omni_")) {
    const cors = buildCorsHeaders(origin, []);
    return {
      error: apiError("Token API tidak valid atau tidak ada.", "UNAUTHORIZED", 401, cors),
    };
  }

  const tokenHash = await hashApiToken(bearer);

  const { data: row, error } = await admin
    .from("organization_omnichannel_api_tokens")
    .select(
      "id, organization_id, web_id, allowed_origins, whatsapp_invoice_template_name, whatsapp_lead_template_name, is_active, expires_at, token_type",
    )
    .eq("token_hash", tokenHash)
    .maybeSingle();

  const allowedOrigins = Array.isArray(row?.allowed_origins)
    ? (row!.allowed_origins as string[])
    : [];
  const corsHeaders = buildCorsHeaders(origin, allowedOrigins);

  if (error || !row) {
    return {
      error: apiError("Token API tidak dikenali.", "UNAUTHORIZED", 401, corsHeaders),
    };
  }

  if (!row.is_active) {
    return {
      error: apiError("Token API telah dicabut.", "FORBIDDEN", 403, corsHeaders),
    };
  }

  if (isOmnichannelApiTokenExpired(row.expires_at)) {
    return {
      error: apiError("Token API sudah kedaluwarsa.", "FORBIDDEN", 403, corsHeaders),
    };
  }

  const rateErr = await checkRateLimit(admin, row.id, corsHeaders);
  if (rateErr) return { error: rateErr };

  void admin
    .from("organization_omnichannel_api_tokens")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", row.id);

  return {
    ctx: {
      tokenId: row.id,
      organizationId: row.organization_id,
      webId: row.web_id,
      allowedOrigins,
      whatsappInvoiceTemplateName: row.whatsapp_invoice_template_name ?? null,
      whatsappLeadTemplateName: row.whatsapp_lead_template_name ?? null,
      tokenType: normalizeTokenType(row.token_type),
    },
    corsHeaders,
  };
}

async function checkRateLimit(
  admin: SupabaseClient,
  tokenId: string,
  corsHeaders: Record<string, string>,
): Promise<Response | null> {
  const now = new Date();
  const windowStart = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours(), now.getUTCMinutes()),
  ).toISOString();

  const { data: existing } = await admin
    .from("organization_omnichannel_api_rate_limits")
    .select("request_count")
    .eq("token_id", tokenId)
    .eq("window_start", windowStart)
    .maybeSingle();

  const count = (existing?.request_count as number | undefined) ?? 0;
  if (count >= RATE_LIMIT_PER_MINUTE) {
    return apiError(
      "Batas permintaan terlampaui (100/menit). Coba lagi nanti.",
      "RATE_LIMITED",
      429,
      corsHeaders,
    );
  }

  await admin.from("organization_omnichannel_api_rate_limits").upsert(
    {
      token_id: tokenId,
      window_start: windowStart,
      request_count: count + 1,
    },
    { onConflict: "token_id,window_start" },
  );

  return null;
}

export function isUuid(v: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
}

/** Respons JSON standar API publik Omnichannel (Bahasa Indonesia di pesan error). */

export type ApiErrorCode =
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "BROWSER_REQUEST_REJECTED"
  | "VALIDATION_ERROR"
  | "NOT_FOUND"
  | "CONFLICT"
  | "RATE_LIMITED"
  | "LEAD_NOT_MATCHED"
  | "SESSION_NOT_READY"
  | "INTERNAL_ERROR";

export function apiJson(
  body: Record<string, unknown>,
  status: number,
  corsHeaders: Record<string, string>,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

export function apiSuccess(
  data: Record<string, unknown>,
  status: number,
  corsHeaders: Record<string, string>,
): Response {
  return apiJson({ success: true, ...data }, status, corsHeaders);
}

export function apiError(
  error: string,
  code: ApiErrorCode,
  status: number,
  corsHeaders: Record<string, string>,
  details?: unknown,
): Response {
  return apiJson(
    {
      success: false,
      error,
      code,
      ...(details !== undefined ? { details } : {}),
    },
    status,
    corsHeaders,
  );
}

export function buildCorsHeaders(origin: string | null, allowedOrigins: string[]): Record<string, string> {
  const base = {
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Max-Age": "86400",
  };

  if (!origin) {
    return { ...base, "Access-Control-Allow-Origin": "*" };
  }

  const normalized = origin.trim().toLowerCase();
  const allowed = allowedOrigins.map((o) => o.trim().toLowerCase()).filter(Boolean);

  if (allowed.length === 0) {
    return { ...base, "Access-Control-Allow-Origin": "*" };
  }

  if (allowed.includes(normalized) || allowed.includes("*")) {
    return { ...base, "Access-Control-Allow-Origin": origin };
  }

  return { ...base, "Access-Control-Allow-Origin": "null" };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const DEFAULT_DEBOUNCE_SECONDS = 45;

export function scheduleAnalyticsRollupRefresh(admin: SupabaseClient, webId: string): void {
  const key = webId.trim().toLowerCase();
  if (!key) return;

  void admin
    .rpc("maybe_refresh_analytics_rollups", {
      p_web_id: key,
      p_debounce_seconds: DEFAULT_DEBOUNCE_SECONDS,
    })
    .then(({ data, error }) => {
      if (error) {
        console.error("scheduleAnalyticsRollupRefresh:", error.message);
        return;
      }
      const status = (data as { status?: string } | null)?.status;
      if (status === "error") {
        console.error("scheduleAnalyticsRollupRefresh:", JSON.stringify(data));
      }
    })
    .catch((e) => {
      console.error("scheduleAnalyticsRollupRefresh:", e);
    });
}

