export const FLOATING_WA_LEAD_SOURCE = "WhatsApp floating click";
const FLOATING_WA_CLIENT = "WhatsApp floating click";
const FLOATING_WA_TITLE = "Floating WA click";

export type SyncFloatingWaClickParams = {
  sessionId: string;
  visitorId: string;
  path: string;
  targetUrl: string | null;
  targetPhone: string | null;
  waClickId: string;
};

export type SyncFloatingWaClickResult =
  | { ok: true; leadId: string; leadCreated: boolean }
  | { ok: false; error: string };

export type FloatingStubLeadRef = {
  leadId: string;
  submissionId: string | null;
};

export async function findFloatingStubLead(
  admin: SupabaseClient,
  organizationId: string,
  webId: string,
  sessionId: string,
): Promise<FloatingStubLeadRef | null> {
  const { data: lead, error: leadErr } = await admin
    .from("leads")
    .select("id, source")
    .eq("organization_id", organizationId)
    .eq("web_id", webId)
    .eq("analytics_session_id", sessionId)
    .maybeSingle();

  if (leadErr || !lead?.id) return null;

  const isFloatingSource = lead.source === FLOATING_WA_LEAD_SOURCE;

  const { data: drafts } = await admin
    .from("lead_submissions")
    .select("id, form_data, status")
    .eq("lead_id", lead.id)
    .eq("organization_id", organizationId)
    .eq("status", "draft")
    .eq("is_active", true);

  const floatingDraft = (drafts ?? []).find((row) => {
    const fd = row.form_data as Record<string, unknown> | null;
    return fd?.source === "floating_whatsapp";
  });

  if (!isFloatingSource && !floatingDraft) return null;

  return {
    leadId: String(lead.id),
    submissionId: floatingDraft?.id != null ? String(floatingDraft.id) : null,
  };
}

/** Backfill attribution on floating stub when traffic-logs arrives after wa-link-clicks. */
export async function patchFloatingStubAttributionFromSession(
  admin: SupabaseClient,
  organizationId: string,
  webId: string,
  sessionId: string,
  session: SessionMarketingRow,
): Promise<void> {
  const marketing = resolveSessionMarketingAttribution(sessionId, webId, session);
  if (!marketing.attributionLabel && !marketing.attribution.utm_source) return;

  const { error } = await admin
    .from("leads")
    .update({
      attribution: marketing.attribution,
      attribution_label: marketing.attributionLabel,
      gclid: marketing.gclid,
      fbclid: marketing.fbclid,
      updated_at: new Date().toISOString(),
    })
    .eq("organization_id", organizationId)
    .eq("web_id", webId)
    .eq("analytics_session_id", sessionId)
    .eq("source", FLOATING_WA_LEAD_SOURCE)
    .is("attribution", null);

  if (error) {
    console.warn("patchFloatingStubAttributionFromSession:", error);
  }
}

export async function syncFloatingWaClickToLead(
  admin: SupabaseClient,
  ctx: OmnichannelApiTokenContext,
  params: SyncFloatingWaClickParams,
): Promise<SyncFloatingWaClickResult> {
  const { sessionId, visitorId, path, targetUrl, targetPhone, waClickId } = params;

  const sessionResult = await ensureAnalyticsSessionForIngest(admin, ctx, {
    sessionId,
    visitorId,
  });
  const session = sessionResult.ok ? sessionResult.session : null;

  const marketing = session
    ? resolveSessionMarketingAttribution(sessionId, ctx.webId, session)
    : {
        attribution: { session_id: sessionId, web_id: ctx.webId },
        attributionLabel: null,
        gclid: null,
        fbclid: null,
      };

  const existing = await findFloatingStubLead(
    admin,
    ctx.organizationId,
    ctx.webId,
    sessionId,
  );

  const now = new Date().toISOString();

  if (existing) {
    const patch: Record<string, unknown> = { updated_at: now };
    if (marketing.attributionLabel || marketing.attribution.utm_source) {
      const { data: current } = await admin
        .from("leads")
        .select("attribution, attribution_label, gclid, fbclid")
        .eq("id", existing.leadId)
        .maybeSingle();

      if (!current?.attribution) patch.attribution = marketing.attribution;
      if (!current?.attribution_label && marketing.attributionLabel) {
        patch.attribution_label = marketing.attributionLabel;
      }
      if (!current?.gclid && marketing.gclid) patch.gclid = marketing.gclid;
      if (!current?.fbclid && marketing.fbclid) patch.fbclid = marketing.fbclid;
    }

    const { error: updErr } = await admin
      .from("leads")
      .update(patch)
      .eq("id", existing.leadId);

    if (updErr) {
      return { ok: false, error: updErr.message };
    }

    return { ok: true, leadId: existing.leadId, leadCreated: false };
  }

  const actor = await getOrCreateSystemActor(admin, ctx.organizationId);
  const statusId = await resolveLeadStatusId(admin, ctx.organizationId, "new");
  const leadId = crypto.randomUUID();

  const { error: leadErr } = await admin.from("leads").insert({
    id: leadId,
    client: FLOATING_WA_CLIENT,
    title: FLOATING_WA_TITLE,
    category: "Website API",
    created_by: actor.userId,
    created_by_name: actor.displayName,
    assignee: "Unassigned",
    organization_id: ctx.organizationId,
    source: FLOATING_WA_LEAD_SOURCE,
    status_id: statusId,
    phone_number: null,
    email: null,
    attribution: marketing.attribution,
    attribution_label: marketing.attributionLabel,
    web_id: ctx.webId,
    analytics_session_id: sessionId,
    gclid: marketing.gclid,
    fbclid: marketing.fbclid,
    created_at: now,
    updated_at: now,
  });

  if (leadErr) {
    return { ok: false, error: leadErr.message };
  }

  const { error: subErr } = await admin.from("lead_submissions").insert({
    organization_id: ctx.organizationId,
    lead_id: leadId,
    web_id: ctx.webId,
    form_id: null,
    name: FLOATING_WA_CLIENT,
    phone_number: null,
    email: null,
    notes: null,
    form_data: {
      source: "floating_whatsapp",
      path,
      target_url: targetUrl,
      target_phone: targetPhone,
      wa_click_id: waClickId,
      visitor_id: visitorId,
    },
    status: "draft",
    is_active: true,
    updated_at: now,
  });

  if (subErr) {
    await admin.from("leads").delete().eq("id", leadId);
    return { ok: false, error: subErr.message };
  }

  return { ok: true, leadId, leadCreated: true };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

/** Mirrors public.traffic_path_key for client-side comparison. */
export function trafficPathKey(p: string | null | undefined): string {
  if (p == null) return "/";
  let t = String(p).trim().toLowerCase();
  if (t === "" || t === "/") return "/";
  t = t.replace(/^\/+|\/+$/g, "");
  if (t === "") return "/";
  return t.startsWith("/") ? t : `/${t}`;
}

export type ResolvedClickPath = {
  path: string;
  pathClient: string | null;
};

function pathnameFromUrl(url: string | null | undefined): string | null {
  if (!url) return null;
  try {
    const parsed = new URL(url, "https://placeholder.local");
    const p = parsed.pathname || "/";
    return p.startsWith("/") ? p : `/${p}`;
  } catch {
    return null;
  }
}

/**
 * Resolve click path from active page_view at click time.
 * When client path mismatches, store original in pathClient only for the
 * classic SPA nav bug (client sent destination path while still on source page).
 */
export async function resolveClickPathFromPageView(
  admin: SupabaseClient,
  params: {
    sessionId: string;
    clientPath: string;
    clickAt?: string;
    pageViewId?: string | null;
    targetUrl?: string | null;
  },
): Promise<ResolvedClickPath> {
  const clientPath = String(params.clientPath ?? "/").trim() || "/";
  const clickAt = params.clickAt ?? new Date().toISOString();
  const targetPath = pathnameFromUrl(params.targetUrl);

  const applyResolved = (resolvedPath: string): ResolvedClickPath => {
    if (trafficPathKey(resolvedPath) === trafficPathKey(clientPath)) {
      return { path: clientPath, pathClient: null };
    }
    const clientLooksLikeDestination =
      targetPath != null && trafficPathKey(targetPath) === trafficPathKey(clientPath);
    if (!clientLooksLikeDestination) {
      return { path: clientPath, pathClient: null };
    }
    return { path: resolvedPath, pathClient: clientPath };
  };

  if (params.pageViewId) {
    const { data: pv } = await admin
      .from("analytics_page_views")
      .select("id, path")
      .eq("id", params.pageViewId)
      .eq("session_id", params.sessionId)
      .maybeSingle();

    if (pv?.path != null) {
      return applyResolved(String(pv.path).trim() || "/");
    }
  }

  const { data: pageViews, error } = await admin
    .from("analytics_page_views")
    .select("id, path, started_at")
    .eq("session_id", params.sessionId)
    .lte("started_at", clickAt)
    .order("started_at", { ascending: false })
    .limit(1);

  if (error || !pageViews?.length) {
    return { path: clientPath, pathClient: null };
  }

  const active = pageViews[0];
  return applyResolved(String(active.path ?? "/").trim() || "/");
}

/** Ekstraksi UTM dan click ID dari URL landing page. */

export type ParsedUrlParams = {
  utm_source: string | null;
  utm_medium: string | null;
  utm_campaign: string | null;
  utm_term: string | null;
  utm_content: string | null;
  gclid: string | null;
  fbclid: string | null;
  msclkid: string | null;
  gbraid: string | null;
  wbraid: string | null;
  path: string;
};

function pickParam(searchParams: URLSearchParams, key: string): string | null {
  const v = searchParams.get(key);
  return v && v.trim() ? v.trim() : null;
}

export function parsePageUrl(raw: string): ParsedUrlParams | null {
  try {
    const url = new URL(raw);
    const sp = url.searchParams;
    return {
      utm_source: pickParam(sp, "utm_source"),
      utm_medium: pickParam(sp, "utm_medium"),
      utm_campaign: pickParam(sp, "utm_campaign"),
      utm_term: pickParam(sp, "utm_term"),
      utm_content: pickParam(sp, "utm_content"),
      gclid: pickParam(sp, "gclid"),
      fbclid: pickParam(sp, "fbclid"),
      msclkid: pickParam(sp, "msclkid"),
      gbraid: pickParam(sp, "gbraid"),
      wbraid: pickParam(sp, "wbraid"),
      path: url.pathname || "/",
    };
  } catch {
    return null;
  }
}

export function coalesceUtm(
  body: Record<string, unknown>,
  parsed: ParsedUrlParams | null,
): ParsedUrlParams {
  return {
    utm_source: strOr(body.utm_source) ?? parsed?.utm_source ?? null,
    utm_medium: strOr(body.utm_medium) ?? parsed?.utm_medium ?? null,
    utm_campaign: strOr(body.utm_campaign) ?? parsed?.utm_campaign ?? null,
    utm_term: strOr(body.utm_term) ?? parsed?.utm_term ?? null,
    utm_content: strOr(body.utm_content) ?? parsed?.utm_content ?? null,
    gclid: strOr(body.gclid) ?? parsed?.gclid ?? null,
    fbclid: strOr(body.fbclid) ?? parsed?.fbclid ?? null,
    msclkid: strOr(body.msclkid) ?? parsed?.msclkid ?? null,
    gbraid: strOr(body.gbraid) ?? parsed?.gbraid ?? null,
    wbraid: strOr(body.wbraid) ?? parsed?.wbraid ?? null,
    path: parsed?.path ?? "/",
  };
}

function strOr(v: unknown): string | null {
  if (v == null) return null;
  const s = String(v).trim();
  return s || null;
}

