  utm_campaign?: string | null;
  utm_content?: string | null;
  utm_term?: string | null;
  first_utm_source?: string | null;
  first_utm_medium?: string | null;
  first_utm_campaign?: string | null;
  first_utm_content?: string | null;
  first_utm_term?: string | null;
  last_utm_source?: string | null;
  last_utm_medium?: string | null;
  last_utm_campaign?: string | null;
  last_utm_content?: string | null;
  last_utm_term?: string | null;
  gclid?: string | null;
  fbclid?: string | null;
  has_gclid?: boolean;
  first_has_gclid?: boolean;
  last_has_gclid?: boolean;
  has_fbclid?: boolean;
  first_has_fbclid?: boolean;
  last_has_fbclid?: boolean;
  has_msclkid?: boolean;
  has_gbraid?: boolean;
  has_wbraid?: boolean;
};

function stickyString(
  incoming: string | null,
  ...existing: (string | null | undefined)[]
): string | null {
  if (incoming) return incoming;
  for (const value of existing) {
    const normalized = strOr(value);
    if (normalized) return normalized;
  }
  return null;
}

function stickyBool(
  incomingPresent: boolean,
  ...existing: (boolean | null | undefined)[]
): boolean {
  if (incomingPresent) return true;
  return existing.some((value) => value === true);
}

function mergeUtmDimension(
  incoming: string | null,
  existing: SessionAttributionRow,
  firstKey: keyof SessionAttributionRow,
  utmKey: keyof SessionAttributionRow,
  lastKey: keyof SessionAttributionRow,
): {
  firstTouch: string | null;
  lastTouch: string | null;
} {
  const firstTouch = stickyString(
    incoming,
    existing[firstKey] as string | null | undefined,
    existing[utmKey] as string | null | undefined,
  );
  const lastTouch = stickyString(
    incoming,
    existing[lastKey] as string | null | undefined,
    existing[firstKey] as string | null | undefined,
    existing[utmKey] as string | null | undefined,
  );
  return { firstTouch, lastTouch };
}

/** Sticky session attribution merge for SPA page views without UTM query params. */
export function mergeIncomingAttribution(
  existing: SessionAttributionRow,
  incoming: ParsedUrlParams,
  ctx: { now: string; pageUrl: string; referrer: string | null; visitorId: string },
): SessionAttributionMergePatch {
  const source = mergeUtmDimension(
    incoming.utm_source,
    existing,
    "first_utm_source",
    "utm_source",
    "last_utm_source",
  );
  const medium = mergeUtmDimension(
    incoming.utm_medium,
    existing,
    "first_utm_medium",
    "utm_medium",
    "last_utm_medium",
  );
  const campaign = mergeUtmDimension(
    incoming.utm_campaign,
    existing,
    "first_utm_campaign",
    "utm_campaign",
    "last_utm_campaign",
  );
  const content = mergeUtmDimension(
    incoming.utm_content,
    existing,
    "first_utm_content",
    "utm_content",
    "last_utm_content",
  );
  const term = mergeUtmDimension(
    incoming.utm_term,
    existing,
    "first_utm_term",
    "utm_term",
    "last_utm_term",
  );

  const gclid = stickyString(incoming.gclid, existing.gclid);
  const fbclid = stickyString(incoming.fbclid, existing.fbclid);
  const hasGclid = stickyBool(Boolean(incoming.gclid), existing.has_gclid, existing.first_has_gclid, existing.last_has_gclid);
  const hasFbclid = stickyBool(
    Boolean(incoming.fbclid),
    existing.has_fbclid,
    existing.first_has_fbclid,
    existing.last_has_fbclid,
  );
  const hasMsclkid = stickyBool(Boolean(incoming.msclkid), existing.has_msclkid);
  const hasGbraid = stickyBool(Boolean(incoming.gbraid), existing.has_gbraid);
  const hasWbraid = stickyBool(Boolean(incoming.wbraid), existing.has_wbraid);

  const patch: SessionAttributionMergePatch = {
    last_seen_at: ctx.now,
    last_landing_url: ctx.pageUrl,
    last_referrer: ctx.referrer,
    visitor_id: ctx.visitorId,
    last_utm_source: source.lastTouch,
    last_utm_medium: medium.lastTouch,
    last_utm_campaign: campaign.lastTouch,
    last_utm_content: content.lastTouch,
    last_utm_term: term.lastTouch,
    has_gclid: hasGclid,
    last_has_gclid: hasGclid,
    has_fbclid: hasFbclid,
    last_has_fbclid: hasFbclid,
    has_msclkid: hasMsclkid,
    has_gbraid: hasGbraid,
    has_wbraid: hasWbraid,
  };

  if (gclid) patch.gclid = gclid;
  if (fbclid) patch.fbclid = fbclid;

  if (!strOr(existing.utm_source) && source.firstTouch) {
    patch.utm_source = source.firstTouch;
    patch.first_utm_source = source.firstTouch;
  }
  if (!strOr(existing.utm_medium) && medium.firstTouch) {
    patch.utm_medium = medium.firstTouch;
    patch.first_utm_medium = medium.firstTouch;
  }
  if (!strOr(existing.utm_campaign) && campaign.firstTouch) {
    patch.utm_campaign = campaign.firstTouch;
    patch.first_utm_campaign = campaign.firstTouch;
  }
  if (!strOr(existing.utm_content) && content.firstTouch) {
    patch.utm_content = content.firstTouch;
    patch.first_utm_content = content.firstTouch;
  }
  if (!strOr(existing.utm_term) && term.firstTouch) {
    patch.utm_term = term.firstTouch;
    patch.first_utm_term = term.firstTouch;
  }

  if (!existing.first_has_gclid && hasGclid) patch.first_has_gclid = true;
  if (!existing.first_has_fbclid && hasFbclid) patch.first_has_fbclid = true;

  if (incoming.utm_source && strOr(existing.utm_source)) {
    patch.last_utm_source = incoming.utm_source;
  }
  if (incoming.utm_medium && strOr(existing.utm_medium)) {
    patch.last_utm_medium = incoming.utm_medium;
  }
  if (incoming.utm_campaign && strOr(existing.utm_campaign)) {
    patch.last_utm_campaign = incoming.utm_campaign;
  }
  if (incoming.utm_content && strOr(existing.utm_content)) {
    patch.last_utm_content = incoming.utm_content;
  }
  if (incoming.utm_term && strOr(existing.utm_term)) {
    patch.last_utm_term = incoming.utm_term;
  }

  return patch;
}

export function buildAttributionLabel(utm: ParsedUrlParams): string | null {
  const parts = [utm.utm_source, utm.utm_medium, utm.utm_campaign].filter(Boolean);
  if (parts.length === 0) return null;
  return parts.join(" / ");
}

export function extractFbclidFromUrl(raw: string | null | undefined): string | null {
  if (!raw?.trim()) return null;
  return parsePageUrl(raw)?.fbclid ?? null;
}

/** Resolve gclid/fbclid from session row; fbclid falls back to landing URL when only has_fbclid was stored. */
export type SessionMarketingRow = SessionAttributionRow & {
  landing_url?: string | null;
  last_landing_url?: string | null;
  first_landing_url?: string | null;
};

export type SessionMarketingAttribution = {
  attribution: Record<string, unknown>;
  attributionLabel: string | null;
  gclid: string | null;
  fbclid: string | null;
};

function firstTouchUtm(session: SessionAttributionRow): Pick<
  ParsedUrlParams,
  "utm_source" | "utm_medium" | "utm_campaign" | "utm_term" | "utm_content"
> {
  return {
    utm_source: strOr(session.first_utm_source) ?? strOr(session.utm_source),
    utm_medium: strOr(session.first_utm_medium) ?? strOr(session.utm_medium),
    utm_campaign: strOr(session.first_utm_campaign) ?? strOr(session.utm_campaign),
    utm_content: strOr(session.first_utm_content) ?? strOr(session.utm_content),
    utm_term: strOr(session.first_utm_term) ?? strOr(session.utm_term),
  };
}

/** First-touch UTM + click IDs from analytics_sessions for leads / wa-click attribution. */
export function resolveSessionMarketingAttribution(
  sessionId: string,
  webId: string,
  session: SessionMarketingRow,
): SessionMarketingAttribution {
  const utm = firstTouchUtm(session);
  const clickIds = resolveSessionClickIds(session);
  const landingUrl =
    session.last_landing_url ?? session.landing_url ?? session.first_landing_url ?? null;

  const attribution: Record<string, unknown> = {
    session_id: sessionId,
    web_id: webId,
    utm_source: utm.utm_source,
    utm_medium: utm.utm_medium,
    utm_campaign: utm.utm_campaign,
    utm_content: utm.utm_content,
    utm_term: utm.utm_term,
    landing_url: landingUrl,
    gclid: clickIds.gclid,
    fbclid: clickIds.fbclid,
  };

  const attributionLabel = buildAttributionLabel({
    ...utm,
    gclid: clickIds.gclid,
    fbclid: clickIds.fbclid,
    msclkid: null,
    gbraid: null,
    wbraid: null,
    path: "/",
  });

  return {
    attribution,
    attributionLabel,
    gclid: clickIds.gclid,
    fbclid: clickIds.fbclid,
  };
}

export function resolveSessionClickIds(session: {
  gclid?: string | null;
  fbclid?: string | null;
  has_fbclid?: boolean | null;
  landing_url?: string | null;
  last_landing_url?: string | null;
  first_landing_url?: string | null;
}): { gclid: string | null; fbclid: string | null } {
  const landing =
    session.last_landing_url ?? session.landing_url ?? session.first_landing_url ?? null;
  const fbFromCol = session.fbclid?.trim() || null;
  const fbclid =
    fbFromCol ??
    (session.has_fbclid ? extractFbclidFromUrl(landing) : null) ??
    extractFbclidFromUrl(landing);
  return {
    gclid: session.gclid?.trim() || null,
    fbclid,
  };
}

export function isValidWebId(webId: string): boolean {
  return /^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$/.test(webId) || /^[a-z0-9]{3,64}$/.test(webId);
}

export function normalizeWebId(raw: string): string {
  return raw.trim().toLowerCase();
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const STATUS_MAP: Record<string, string[]> = {
  new: ["Open", "New"],
  contacted: ["On Progress", "Contacted", "In Progress"],
  deal: ["Converted", "Deal", "Closed Won"],
  lost: ["Lost", "Closed", "Closed Lost"],
};

export async function resolveLeadStatusId(
  admin: SupabaseClient,
  organizationId: string,
  apiStatus?: string | null,
): Promise<string | null> {
  const key = (apiStatus ?? "new").trim().toLowerCase();
  const candidates = STATUS_MAP[key] ?? STATUS_MAP.new;

  for (const name of candidates) {
    const { data } = await admin
      .from("lead_statuses")
      .select("id")
      .eq("organization_id", organizationId)
      .ilike("name", name)
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    if (data?.id) return data.id as string;
  }

  const { data: fallback } = await admin
    .from("lead_statuses")
    .select("id")
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .order("sort_order", { ascending: true })
    .limit(1)
    .maybeSingle();

  return (fallback?.id as string | undefined) ?? null;
}

export async function resolveConvertedStatusId(
  admin: SupabaseClient,
  organizationId: string,
): Promise<string | null> {
  return resolveLeadStatusId(admin, organizationId, "deal");
}

export async function getOrCreateSystemActor(
  admin: SupabaseClient,
  organizationId: string,
): Promise<{ userId: string; displayName: string }> {
  const { data, error } = await admin.rpc("get_or_create_org_api_system_actor", {
    p_organization_id: organizationId,
  });

  if (error) throw error;
  const row = Array.isArray(data) ? data[0] : data;
  if (!row?.user_id) {
    throw new Error("System actor tidak ditemukan untuk organisasi ini.");
  }
  return {
    userId: String(row.user_id),
    displayName: String(row.display_name ?? "Synckerja API"),
  };
}

/** Normalisasi nomor telepon Indonesia untuk pencocokan lead. */

export function normalizePhone(raw: string | null | undefined): string | null {
  if (raw == null) return null;
  let digits = String(raw).replace(/\D/g, "");
  if (!digits) return null;
  if (digits.startsWith("62")) {
    return digits;
  }
  if (digits.startsWith("0")) {
    return "62" + digits.slice(1);
  }
  return digits;
}

export function normalizeEmail(raw: string | null | undefined): string | null {
  if (raw == null) return null;
  const s = String(raw).trim().toLowerCase();
  return s || null;
}

export const RESERVED_LEAD_BODY_KEYS = new Set([
  "name",
  "phone_number",
  "email",
  "notes",
  "session_id",
  "status",
]);

export const MAX_FORM_DATA_KEYS = 64;
export const MAX_FORM_DATA_BYTES = 32 * 1024;

const FORM_DATA_KEY_PATTERN = /^[a-zA-Z][a-zA-Z0-9_]{0,63}$/;

export type LeadFormCoreFields = {
  name: string;
  phone_number: string;
  email: string;
  notes: string | null;
  session_id: string | null;
  status: string | null;
};

export type ExtractLeadFormResult =
  | { ok: true; core: LeadFormCoreFields; formData: Record<string, unknown> | null }
  | { ok: false; error: string };

function isPrimitiveFormValue(value: unknown): boolean {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

function validateFormDataValue(value: unknown, path: string): string | null {
  if (isPrimitiveFormValue(value)) return null;

  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      const err = validateFormDataValue(value[i], `${path}[${i}]`);
      if (err) return err;
    }
    return null;
  }

  if (value !== null && typeof value === "object") {
    return `${path}: nested object tidak diperbolehkan.`;
  }

  return `${path}: tipe nilai tidak didukung.`;
}

export function validateFormDataRecord(formData: Record<string, unknown>): string | null {
  const keys = Object.keys(formData);
  if (keys.length > MAX_FORM_DATA_KEYS) {
    return `Maksimal ${MAX_FORM_DATA_KEYS} field tambahan per submission.`;
  }

  for (const key of keys) {
    if (!FORM_DATA_KEY_PATTERN.test(key)) {
      return `Nama field "${key}" tidak valid. Gunakan huruf, angka, dan underscore (maks. 64 karakter).`;
    }
    const err = validateFormDataValue(formData[key], key);
    if (err) return err;
  }

  const serialized = JSON.stringify(formData);
  if (serialized.length > MAX_FORM_DATA_BYTES) {
    return `form_data melebihi batas ${MAX_FORM_DATA_BYTES} byte.`;
  }

  return null;
}

export function extractLeadFormPayload(body: Record<string, unknown>): ExtractLeadFormResult {
  const core: LeadFormCoreFields = {
    name: String(body.name ?? "").trim(),
    phone_number: body.phone_number != null ? String(body.phone_number).trim() : "",
    email: body.email != null ? String(body.email).trim() : "",
    notes: body.notes != null ? String(body.notes).trim() || null : null,
    session_id: body.session_id != null ? String(body.session_id).trim() || null : null,
    status: body.status != null ? String(body.status).trim() || null : null,
  };

  const formData: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body)) {
    if (RESERVED_LEAD_BODY_KEYS.has(key)) continue;
    if (value === undefined) continue;
    formData[key] = value;
  }

  const keys = Object.keys(formData);
  if (keys.length === 0) {
    return { ok: true, core, formData: null };
  }

  const validationError = validateFormDataRecord(formData);
  if (validationError) {
    return { ok: false, error: validationError };
  }

  return { ok: true, core, formData };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { resolveLeadWhatsAppBodyParams } from "./leadWhatsAppBodyParams.ts";
import {
  buildWhatsAppPrecheckSkipReason,
  buildWhatsAppSkipReasonMeta,
  fetchLeadTemplateBodySlotCount,
} from "./leadWhatsAppTemplateSlots.ts";
import {
  resolveOrganizationWhatsAppCredentials,
  WA_ACCOUNT_NOT_MAPPED_CODE,
  WA_ACCOUNT_NOT_MAPPED_ERROR,
} from "./resolveOrganizationWhatsAppCredentials.ts";

const META_API_BASE = "https://graph.facebook.com/v21.0";

export type LeadWhatsAppDebugInfo = {
  template_name: string;
  template_language: string;
  mapping_source: "parameter_mapping" | "organization_whatsapp_templates" | "fixed_7";
  param_count: number;
  expected_slot_count: number | null;
  web_id: string;
  whatsapp_account_id?: string | null;
  phone_number_id?: string | null;
  account_resolution?: "mapped" | "not_mapped";
};

export type LeadWhatsAppResult = {
  status: "sent" | "failed" | "skipped" | "pending";
  messageId: string | null;
  skipReason?: string | null;
  error?: string;
  metaErrorCode?: number | null;
  mappingSource?: LeadWhatsAppDebugInfo["mapping_source"];
  paramCount?: number;
  bodyParams?: string[];
  rawMetadata?: Record<string, unknown> | null;
  templateLanguage?: string;
  expectedSlotCount?: number | null;
  debug?: LeadWhatsAppDebugInfo;
};

export { parseLeadConsent } from "./leadWhatsAppBodyParams.ts";

function buildDebugBase(args: {
  templateName: string;
  templateLanguage: string;
  mappingSource: LeadWhatsAppDebugInfo["mapping_source"];
  paramCount: number;
  expectedSlotCount: number | null;
  webId: string;
  whatsappAccountId?: string | null;
  phoneNumberId?: string | null;
  accountResolution?: LeadWhatsAppDebugInfo["account_resolution"];
}): LeadWhatsAppDebugInfo {
  return {
    template_name: args.templateName,
    template_language: args.templateLanguage,
    mapping_source: args.mappingSource,
    param_count: args.paramCount,
    expected_slot_count: args.expectedSlotCount,
    web_id: args.webId,
    whatsapp_account_id: args.whatsappAccountId ?? null,
    phone_number_id: args.phoneNumberId ?? null,
    account_resolution: args.accountResolution,
  };
}

/** Kirim template WhatsApp konfirmasi lead (body params dari organization_whatsapp_templates atau fixed 7). */
export async function triggerLeadWhatsApp(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    webId: string;
    templateName: string;
    orgTemplateLanguage?: string | null;
    phoneNumber: string;
    name: string;
    email: string | null;
    formData: Record<string, unknown> | null;
  },
): Promise<LeadWhatsAppResult> {
  try {
    const creds = await resolveOrganizationWhatsAppCredentials(admin, args.organizationId, {
      webId: args.webId,
    });
    if (!creds.ok) {
      const isNotMapped =
        creds.code === WA_ACCOUNT_NOT_MAPPED_CODE ||
        creds.error === WA_ACCOUNT_NOT_MAPPED_ERROR;
      return {
        status: "skipped",
        messageId: null,
        skipReason: isNotMapped ? WA_ACCOUNT_NOT_MAPPED_ERROR : "wa_not_configured",
        error: creds.error,
        debug: buildDebugBase({
          templateName: args.templateName,
          templateLanguage: String(args.orgTemplateLanguage ?? "id").trim() || "id",
          mappingSource: "fixed_7",
          paramCount: 0,
          expectedSlotCount: null,
          webId: args.webId,
          accountResolution: "not_mapped",
        }),
      };
    }

    const toDigits = args.phoneNumber.replace(/\D/g, "");
    if (!toDigits) {
      return {
        status: "skipped",
        messageId: null,
        skipReason: "no_phone",
        error: "Nomor telepon tidak valid.",
      };
    }

    const resolved = await resolveLeadWhatsAppBodyParams(admin, args);

    const debugBase = buildDebugBase({
      templateName: args.templateName,
      templateLanguage: resolved.language,
      mappingSource: resolved.mappingSource,
      paramCount: resolved.params.length,
      expectedSlotCount: null,
      webId: args.webId,
      whatsappAccountId: creds.credentials.whatsappAccountId,
      phoneNumberId: creds.credentials.phoneNumberId,
      accountResolution: "mapped",
    });

    const slotCheck = await fetchLeadTemplateBodySlotCount(
      admin,
      args.organizationId,
      args.templateName,
      resolved.language,
      args.webId,
    );

    if (slotCheck.ok) {
      debugBase.expected_slot_count = slotCheck.slotCount;
      if (resolved.params.length !== slotCheck.slotCount) {
        const skipReason = buildWhatsAppPrecheckSkipReason({
          templateName: args.templateName,
          templateLanguage: resolved.language,
          mappingSource: resolved.mappingSource,
          paramCount: resolved.params.length,
          expectedSlotCount: slotCheck.slotCount,
          webId: args.webId,
        });
        console.error("triggerLeadWhatsApp precheck:", {
          organizationId: args.organizationId,
          webId: args.webId,
          templateName: args.templateName,
          mappingSource: resolved.mappingSource,
          paramCount: resolved.params.length,
          expectedSlotCount: slotCheck.slotCount,
        });
        return {
          status: "failed",
          messageId: null,
          skipReason,
          error: `Jumlah variabel body (${resolved.params.length}) tidak cocok dengan template Meta (${slotCheck.slotCount}).`,
          mappingSource: resolved.mappingSource,
          paramCount: resolved.params.length,
          expectedSlotCount: slotCheck.slotCount,
          templateLanguage: resolved.language,
          debug: debugBase,
        };
      }
    }

    const payload = {
      messaging_product: "whatsapp",
      to: toDigits,
      type: "template",
      template: {
        name: args.templateName,
        language: { code: resolved.language },
        components: [
          {
            type: "body",
            parameters: resolved.params.map((text) => ({ type: "text", text })),
          },
        ],
      },
    };

    const url = `${META_API_BASE}/${creds.credentials.phoneNumberId}/messages`;
    const res = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${creds.credentials.accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    });

    const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    const metaErr = json.error as { message?: string; code?: number } | undefined;

    if (!res.ok) {
      const errMsg = metaErr?.message ?? `Graph API error ${res.status}`;
      const metaMessage =
        errMsg.startsWith("(#") || metaErr?.code == null
          ? errMsg
          : `(#${metaErr.code}) ${errMsg}`;
      const skipReason = buildWhatsAppSkipReasonMeta({
        metaMessage,
        templateName: args.templateName,
        templateLanguage: resolved.language,
        mappingSource: resolved.mappingSource,
        paramCount: resolved.params.length,
        webId: args.webId,
        expectedSlotCount: debugBase.expected_slot_count,
      });
      console.error("triggerLeadWhatsApp:", {
        organizationId: args.organizationId,
        webId: args.webId,
        templateName: args.templateName,
        mappingSource: resolved.mappingSource,
        paramCount: resolved.params.length,
        expectedSlotCount: debugBase.expected_slot_count,
        params: resolved.params,
        metaError: json,
      });
      return {
        status: "failed",
        messageId: null,
        skipReason,
        error: errMsg,
        metaErrorCode: metaErr?.code ?? null,
        mappingSource: resolved.mappingSource,
        paramCount: resolved.params.length,
        expectedSlotCount: debugBase.expected_slot_count,
        templateLanguage: resolved.language,
        debug: debugBase,
      };
    }

    const messages = json.messages as Array<{ id?: string }> | undefined;
    const messageId = messages?.[0]?.id ?? null;
    return {
      status: "sent",
      messageId: messageId ? String(messageId) : null,
      mappingSource: resolved.mappingSource,
      paramCount: resolved.params.length,
      bodyParams: resolved.params,
      rawMetadata: json,
      templateLanguage: resolved.language,
      expectedSlotCount: debugBase.expected_slot_count,
    };
  } catch (e) {
    console.error("triggerLeadWhatsApp:", e);
    return {
      status: "failed",
      messageId: null,
      skipReason: `meta:${e instanceof Error ? e.message : "Unknown error"}`.slice(0, 500),
      error: e instanceof Error ? e.message : "Unknown error",
    };
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  buildParamsFromMapping,
  parseParameterMapping,
  paramOrDash,
  type LeadMappingSource,
} from "./leadTemplateMapping.ts";

export type { LeadMappingSource };

export type LeadWhatsAppTemplateConfig = {
  templateName: string;
  templateLanguage: string;
  bodyKeys: string[];
  mappingSource: LeadMappingSource;
};

/** Fixed 7-param map (API docs default) when no org template row exists. */
export function buildLeadWhatsAppBodyParamsFixed(args: {
  name: string;
  email: string | null;
  phoneNumber: string;
  formData: Record<string, unknown> | null;
}): string[] {
  const fd = args.formData ?? {};
  return [
    paramOrDash(args.name),
    paramOrDash(args.email),
    paramOrDash(args.phoneNumber),
    paramOrDash(fd.package_label),
    paramOrDash(fd.event_date),
    paramOrDash(fd.event_time),
    paramOrDash(fd.event_address),
  ];
}

export function buildLeadWhatsAppBodyParamsFromKeys(
  bodyKeys: string[],
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    formData: Record<string, unknown> | null;
  },
): string[] {
  return buildParamsFromMapping(bodyKeys, args);
}

export function parseLeadConsent(
  body: Record<string, unknown>,
  formData: Record<string, unknown> | null,
): boolean {
  const raw = body.consent ?? formData?.consent;
  if (raw === true) return true;
  if (raw === false) return false;
  if (typeof raw === "string" && raw.trim().toLowerCase() === "true") return true;
  return false;
}

function parseLegacyBodyKeys(bodyKeysRaw: unknown): string[] {
  return String(bodyKeysRaw ?? "")
    .split(",")
    .map((k) => k.trim())
    .filter(Boolean);
}

/** Load per-web_id template mapping (parameter_mapping or legacy body_keys). */
export async function loadLeadWhatsAppTemplateConfig(
  admin: SupabaseClient,
  organizationId: string,
  webId: string,
  templateName: string,
): Promise<LeadWhatsAppTemplateConfig | null> {
  const normalizedWebId = webId.trim().toLowerCase();
  const normalizedTemplate = templateName.trim();

  const { data: row } = await admin
    .from("organization_whatsapp_templates")
    .select("template_name, template_language, parameter_mapping, body_keys, is_active")
    .eq("organization_id", organizationId)
    .eq("web_id", normalizedWebId)
    .eq("purpose", "lead")
    .eq("template_name", normalizedTemplate)
    .eq("is_active", true)
    .maybeSingle();

  if (!row) return null;

  const templateLanguage = String(row.template_language ?? "id").trim() || "id";
  const templateNameResolved = String(row.template_name ?? normalizedTemplate);

  const mappedKeys = parseParameterMapping(row.parameter_mapping);
  if (mappedKeys && mappedKeys.length > 0) {
    return {
      templateName: templateNameResolved,
      templateLanguage,
      bodyKeys: mappedKeys,
      mappingSource: "parameter_mapping",
    };
  }

  const legacyKeys = parseLegacyBodyKeys(row.body_keys);
  if (legacyKeys.length > 0) {
    return {
      templateName: templateNameResolved,
      templateLanguage,
      bodyKeys: legacyKeys,
      mappingSource: "organization_whatsapp_templates",
    };
  }

  return null;
}

export async function resolveLeadWhatsAppBodyParams(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    webId: string;
    templateName: string;
    orgTemplateLanguage?: string | null;
    name: string;
    email: string | null;
    phoneNumber: string;
    formData: Record<string, unknown> | null;
  },
): Promise<{ params: string[]; language: string; mappingSource: LeadMappingSource }> {
  const config = await loadLeadWhatsAppTemplateConfig(
    admin,
    args.organizationId,
    args.webId,
    args.templateName,
  );

  if (config) {
    if (
      config.mappingSource === "parameter_mapping" &&
      config.bodyKeys.length === 0
    ) {
      console.error("resolveLeadWhatsAppBodyParams: empty parameter_mapping", {
        organizationId: args.organizationId,
        webId: args.webId,
        templateName: args.templateName,
      });
    }

    return {
      params: buildLeadWhatsAppBodyParamsFromKeys(config.bodyKeys, args),
      language: config.templateLanguage,
      mappingSource: config.mappingSource,
    };
  }

  const orgLanguage = String(args.orgTemplateLanguage ?? "id").trim() || "id";

  return {
    params: buildLeadWhatsAppBodyParamsFixed(args),
    language: orgLanguage,
    mappingSource: "fixed_7",
  };
}

import { RESERVED_LEAD_BODY_KEYS } from "./leadFormData.ts";

export type LeadMappingSource =
  | "parameter_mapping"
  | "organization_whatsapp_templates"
  | "fixed_7";

const FORM_DATA_KEY_PATTERN = /^[a-zA-Z][a-zA-Z0-9_]{0,63}$/;

const CORE_MAPPABLE_KEYS = new Set(["name", "email", "phone_number", "notes"]);

const FIXED_7_KEYS = [
  "name",
  "email",
  "phone_number",
  "package_label",
  "event_date",
  "event_time",
  "event_address",
] as const;

export function sanitizeMetaTemplateParam(value: string): string {
  return value
    .replace(/\r\n/g, "\n")
    .replace(/[\n\r]+/g, " · ")
    .replace(/\t/g, " ")
    .replace(/ {5,}/g, "    ")
    .trim()
    .slice(0, 1024);
}

export function paramOrDash(value: unknown): string {
  const s = value == null ? "" : String(value).trim();
  if (s.length === 0) return "-";
  return sanitizeMetaTemplateParam(s);
}

export function isValidLeadMappableFieldKey(key: string): boolean {
  const trimmed = key.trim();
  if (!trimmed) return false;
  if (CORE_MAPPABLE_KEYS.has(trimmed)) return true;
  if (RESERVED_LEAD_BODY_KEYS.has(trimmed)) return false;
  return FORM_DATA_KEY_PATTERN.test(trimmed);
}

/** Parse jsonb parameter_mapping → ordered body keys (slot 1..n). */
export function parseParameterMapping(
  raw: unknown,
  slotCount?: number,
): string[] | null {
  if (raw == null || typeof raw !== "object" || Array.isArray(raw)) return null;
  const obj = raw as Record<string, unknown>;
  const entries = Object.entries(obj)
    .map(([slot, field]) => ({
      slot: Number.parseInt(slot, 10),
      field: String(field ?? "").trim(),
    }))
    .filter((e) => Number.isFinite(e.slot) && e.slot >= 1 && e.field.length > 0)
    .sort((a, b) => a.slot - b.slot);

  if (entries.length === 0) return null;

  const maxSlot = entries[entries.length - 1]!.slot;
  const expected = slotCount ?? maxSlot;
  if (entries.length !== expected) return null;

  for (let i = 1; i <= expected; i++) {
    const found = entries.find((e) => e.slot === i);
    if (!found) return null;
    if (!isValidLeadMappableFieldKey(found.field)) return null;
  }

  return entries.map((e) => e.field);
}

/** Build Record<number, string> from string[] keys for UI. */
export function bodyKeysToParameterMapping(bodyKeys: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  bodyKeys.forEach((key, idx) => {
    out[String(idx + 1)] = key;
  });
  return out;
}

export function resolveBodyKeyValue(
  key: string,
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    notes?: string | null;
    formData: Record<string, unknown> | null;
  },
): string {
  const fd = args.formData ?? {};
  const normalized = key.trim().toLowerCase();

  switch (normalized) {
    case "name":
    case "client":
    case "customer_name":
      return paramOrDash(args.name);
    case "email":
      return paramOrDash(args.email);
    case "phone":
    case "phone_number":
    case "customer_phone":
      return paramOrDash(args.phoneNumber);
    case "notes":
      return paramOrDash(args.notes);
    case "package_label":
    case "package":
    case "needs":
    case "ringkasan_kebutuhan":
      return paramOrDash(fd.package_label ?? fd[normalized] ?? fd[key]);
    case "event_date":
      return paramOrDash(fd.event_date);
    case "event_time":
      return paramOrDash(fd.event_time);
    case "event_address":
    case "office_address":
    case "address":
      return paramOrDash(fd.event_address ?? fd.office_address ?? fd.address);
    case "industry":
    case "business_type":
      return paramOrDash(fd[normalized] ?? fd[key]);
    default:
      return paramOrDash(fd[normalized] ?? fd[key]);
  }
}

export function buildParamsFromMapping(
  bodyKeys: string[],
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    notes?: string | null;
    formData: Record<string, unknown> | null;
  },
): string[] {
  return bodyKeys.map((key) => resolveBodyKeyValue(key, args));
}

const PREVIEW_SAMPLE_SUBMISSION = {
  name: "Budi Santoso",
  email: "budi@example.com",
  phoneNumber: "6281234567890",
  notes: null as string | null,
